package com.gameaggregator.webhookservice.domain;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="webhook_attempts") public class WebhookAttempt{@Id public UUID id=UUID.randomUUID();@Column(nullable=false)public UUID deliveryId;@Column(nullable=false)public int attemptNumber;public Integer httpStatus;public String error;@Column(nullable=false)public Instant attemptedAt=Instant.now();protected WebhookAttempt(){}public WebhookAttempt(UUID d,int n,Integer h,String e){deliveryId=d;attemptNumber=n;httpStatus=h;error=e;}}